{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "EBS volumes are not encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root EBS volume. Unencrypted EBS volumes can expose sensitive data if compromised."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration has 'associate_public_ip_address' set to true, which exposes instances to the public internet, increasing the attack surface."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDS access does not require a token",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The launch configuration does not enforce the use of HTTP tokens for the instance metadata service (IMDS). This can allow unauthorized access to sensitive metadata."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  root_block_device {\n    encrypted = true\n  }\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  user_data = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}",
  "fix_summary": "Disabled public IP address assignment, enabled encryption for the root EBS volume, and enforced HTTP token requirement for IMDS."
}
